// Builds public/adventure-dex.js for the retro overworld iframe from the app's
// own national dex (src/lib/all-pokemon-data.ts, #1-1025):
//   root.ADV_DEX = [[id, name, types, bst, rarity], ...]
// Run: bun run scripts/gen-adventure-dex.ts
import fs from "fs";
import { ALL_POKEMON } from "../src/lib/all-pokemon-data";

const rows = [...ALL_POKEMON]
  .sort((a, b) => a.id - b.id)
  .map((p) => [p.id, p.name, p.types, p.bst, p.rarity]);
const body =
  "/* GENERATED by scripts/gen-adventure-dex.ts from src/lib/all-pokemon-data.ts. Do not edit. */\n" +
  "(function (root) {\n  root.ADV_DEX = " + JSON.stringify(rows) + ";\n" +
  '})(typeof window !== "undefined" ? window : globalThis);\n';
fs.writeFileSync(new URL("../public/adventure-dex.js", import.meta.url), body);
console.log("adventure-dex.js:", rows.length, "species,", body.length, "bytes");
